"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1572],{62067:e=>{e.exports=JSON.parse('{"functions":[],"properties":[],"types":[{"name":"CountdownPayload","desc":"`UI_COUNTDOWN`. `RootOverlay` converts `duration` into an absolute\\n`endsAt` using the action\'s `serverTime` (falling back to\\n`Workspace:GetServerTimeNow()`), so the timer stays correct regardless of\\nnetwork delay. A `duration` of zero or less is ignored.","fields":[{"name":"duration","lua_type":"number","desc":"Seconds from the dispatch time until the countdown ends"},{"name":"label","lua_type":"string?","desc":"Heading above the digits. Omitted renders digits only"}],"source":{"line":187,"path":"src/Shared/Types/Actions.luau"}},{"name":"ScoreboardTeam","desc":"One row on the scoreboard.","fields":[{"name":"position","lua_type":"number?","desc":"Rank, when the server has already sorted the rows"},{"name":"name","lua_type":"string","desc":"Team display name"},{"name":"color","lua_type":"Color3","desc":"Team color, used for the row accent"},{"name":"score","lua_type":"number","desc":"Current score"}],"source":{"line":203,"path":"src/Shared/Types/Actions.luau"}},{"name":"ScoreboardPayload","desc":"`START_SCOREBOARD` and `UPDATE_SCOREBOARD`, consumed by\\n`ScoreboardPortal`. Both fields are optional so a free-for-all mode can\\nsend only `localScore` and a team mode only `teams`.","fields":[{"name":"teams","lua_type":"{ ScoreboardTeam }?","desc":"Team rows"},{"name":"localScore","lua_type":"number?","desc":"The local player\'s own score"}],"source":{"line":221,"path":"src/Shared/Types/Actions.luau"}},{"name":"GameInfoSummaryPayload","desc":"`GAME_ROUND_SUMMARY`, dispatched by `BaseGameMode` at round end and read\\nthrough the `useRoundInfo` hook. `localRewards` is the receiving player\'s\\nown payout, not a table of everyone\'s.","fields":[{"name":"winners","lua_type":"{ MinigameTypes.EndWinner }","desc":"Placing players, in order"},{"name":"localRewards","lua_type":"MinigameTypes.Rewards","desc":"What this client earned"},{"name":"headline","lua_type":"string?","desc":"The outcome, from the mode\'s `SummaryDetails`"},{"name":"roster","lua_type":"{ MinigameTypes.RosterEntry }?","desc":"Role holders and survivors"},{"name":"teamColors","lua_type":"{ [string]: Color3 }?","desc":"The mode\'s team colors, for role headers"}],"source":{"line":240,"path":"src/Shared/Types/Actions.luau"}},{"name":"GameInfoRoundPayload","desc":"`GAME_ROUND_INFO`, dispatched by `GameService` when a round starts. Drives\\nthe round intro card via `useRoundInfo`. `teams` is absent in free-for-all\\nmodes.","fields":[{"name":"gameMode","lua_type":"string","desc":"Mode identifier"},{"name":"mapName","lua_type":"string","desc":"Map display name"},{"name":"description","lua_type":"string","desc":"Short rules blurb shown on the intro card"},{"name":"thumbnail","lua_type":"string","desc":"Asset id for the map image"},{"name":"gameLength","lua_type":"number","desc":"Round length in seconds"},{"name":"lives","lua_type":"number","desc":"Lives each player starts with"},{"name":"teams","lua_type":"{ { name: string, color: Color3 } }?","desc":"Team roster, for team modes"}],"source":{"line":270,"path":"src/Shared/Types/Actions.luau"}},{"name":"RoleRevealPayload","desc":"`ROUND_ROLE`, dispatched by a game mode to a player when they get a role,\\nand again when one is promoted mid-round. Drives the role reveal splash in\\n`RoundInfoOverlay`. The mode owns all the copy; the client uppercases\\n`caption` and `role`. Fields are documented on `MinigameTypes.RoleReveal`,\\nwhich holds the shape so the client screen can load without `red`.","source":{"line":290,"path":"src/Shared/Types/Actions.luau"}},{"name":"PlacePropPayload","desc":"Places a prop on a plot. `itemRecord` identifies the specific inventory\\nrecord being consumed, so two stacks of the same `propItemId` stay\\ndistinguishable.","fields":[{"name":"propItemId","lua_type":"string","desc":"Which prop to place"},{"name":"itemRecord","lua_type":"Types.ItemRecord?","desc":"Inventory record backing the placement"},{"name":"plotId","lua_type":"string","desc":"Target plot"},{"name":"offset","lua_type":"BaseUtil.PositionData","desc":"Position and rotation within the plot"}],"source":{"line":305,"path":"src/Shared/Types/Actions.luau"}},{"name":"MovePropPayload","desc":"Repositions an already-placed prop. `plotId` is included so a prop can be\\nmoved between plots, not only within one.","fields":[{"name":"propId","lua_type":"string","desc":"Prop being moved"},{"name":"plotId","lua_type":"string","desc":"Destination plot"},{"name":"offset","lua_type":"BaseUtil.PositionData","desc":"New position and rotation within the plot"}],"source":{"line":323,"path":"src/Shared/Types/Actions.luau"}},{"name":"StartPropDestructionPayload","desc":"`BASE_START_PROP_DESTRUCTION`. Begins the timed teardown of a prop;\\n`BASE_REMOVE_PROP` is what finishes it.","fields":[{"name":"propId","lua_type":"string","desc":"Prop to start destroying"}],"source":{"line":338,"path":"src/Shared/Types/Actions.luau"}},{"name":"PropRemoteInputPayload","desc":"`PROP_REMOTE_INPUT` \u2014 the generic escape hatch for prop interactions. A\\nprop class exposes a named method and the client asks for it by name\\nrather than each prop minting its own action.\\n\\n:::warning\\n`functionName` and `args` come straight off the wire. The receiving prop\\nclass is responsible for validating both against its own allowlist.\\n:::","fields":[{"name":"propId","lua_type":"string","desc":"Prop receiving the call"},{"name":"functionName","lua_type":"string","desc":"Method to invoke on the prop class"},{"name":"args","lua_type":"{ any }","desc":"Arguments, forwarded as-is"}],"source":{"line":359,"path":"src/Shared/Types/Actions.luau"}},{"name":"InventoryMoveToHotbarPayload","desc":"`INVENTORY_MOVE_TO_HOTBAR`, dispatched when a bag item is dragged onto a\\nhotbar slot in `InventoryPortal`.","fields":[{"name":"recordId","lua_type":"string","desc":"Inventory record being moved"},{"name":"slotIndex","lua_type":"number","desc":"Destination hotbar slot"}],"source":{"line":375,"path":"src/Shared/Types/Actions.luau"}},{"name":"HotbarMoveToInventoryPayload","desc":"`HOTBAR_MOVE_TO_INVENTORY`, the reverse drag. No slot index \u2014 the server\\nfinds the record\'s current slot.","fields":[{"name":"recordId","lua_type":"string","desc":"Record to move back into the bag"}],"source":{"line":389,"path":"src/Shared/Types/Actions.luau"}},{"name":"HotbarSwapSlotsPayload","desc":"`HOTBAR_SWAP_SLOTS`, dispatched when one hotbar slot is dragged onto\\nanother. Swaps rather than overwrites, so dropping onto an occupied slot\\nnever destroys an item.","fields":[{"name":"fromSlotIndex","lua_type":"number","desc":"Slot dragged from"},{"name":"toSlotIndex","lua_type":"number","desc":"Slot dropped onto"}],"source":{"line":404,"path":"src/Shared/Types/Actions.luau"}},{"name":"InventorySwapBagSlotsPayload","desc":"`INVENTORY_SWAP_BAG_SLOTS`, reordering within the bag. Addressed by record\\nid rather than bag index, so a concurrent server-side reorder cannot make\\nthe swap land on the wrong items.","fields":[{"name":"fromRecordId","lua_type":"string","desc":"Record dragged from"},{"name":"toRecordId","lua_type":"string","desc":"Record dropped onto"}],"source":{"line":420,"path":"src/Shared/Types/Actions.luau"}},{"name":"SoilAddSeedPayload","desc":"Plants a seed in a soil prop. `offset` is a `Vector2` because soil is a\\n2D grid of planting spots.","fields":[{"name":"propId","lua_type":"string","desc":"Soil prop being planted"},{"name":"seedItemId","lua_type":"string","desc":"Seed to plant"},{"name":"offset","lua_type":"Vector2","desc":"Grid cell within the soil"}],"source":{"line":436,"path":"src/Shared/Types/Actions.luau"}},{"name":"AnimalPenAddEggPayload","desc":"The animal-pen counterpart of [SoilAddSeedPayload].","fields":[{"name":"propId","lua_type":"string","desc":"Animal pen receiving the egg"},{"name":"eggItemId","lua_type":"string","desc":"Egg to place"},{"name":"offset","lua_type":"Vector2","desc":"Grid cell within the pen"}],"source":{"line":452,"path":"src/Shared/Types/Actions.luau"}},{"name":"BasePrepareGrowAllCropsPurchasePayload","desc":"Opens the developer-product purchase for growing every crop on a base.\\n\\"Prepare\\" because the client only asks for the prompt; the grant happens\\nwhen the receipt is processed server-side.","fields":[{"name":"ownerId","lua_type":"string","desc":"Base owner whose crops are affected"}],"source":{"line":468,"path":"src/Shared/Types/Actions.luau"}},{"name":"BasePrepareHarvestAllCropsPurchasePayload","desc":"The harvest-all counterpart of [BasePrepareGrowAllCropsPurchasePayload].","fields":[{"name":"ownerId","lua_type":"string","desc":"Base owner whose crops are affected"}],"source":{"line":480,"path":"src/Shared/Types/Actions.luau"}},{"name":"KillEffectPayload","desc":"`KILL_EFFECT`: play a kill effect cosmetic at a victim\'s position.","fields":[{"name":"itemId","lua_type":"string","desc":"KillEffect cosmetic id"},{"name":"position","lua_type":"Vector3","desc":"Victim\'s root position at death"}],"source":{"line":493,"path":"src/Shared/Types/Actions.luau"}}],"name":"Actions","desc":"Payload types for the `red` action protocol, plus \u2014 in this header \u2014 a map\\nof the protocol itself.\\n\\nActions are the *only* client/server channel in the game. There are no\\nloose RemoteEvents; everything crosses the boundary as\\n`red.dispatch({ type = \\"NAME\\", payload = ... })`. This module exports the\\npayload shapes for the actions whose payloads are non-trivial. The action\\nnames themselves are plain strings at their call sites, which is why the\\ninventory below matters.\\n\\n### Reading the protocol\\n\\nThree call shapes appear in the codebase:\\n\\n| Shape | Side | Meaning |\\n| --- | --- | --- |\\n| `red.dispatch({ type = ... })` | either | Send. On the client it goes to the server; on the server, to one or all clients |\\n| `bind(\\"NAME\\", handler)` | server | Register a handler. Handlers live in `Features/*/Handler(s)` modules wired up with `red.useHandler(s)` |\\n| `red.subscribeTo(\\"NAME\\", fn)` | client | Listen. React components use the `useRedAction` hook, which is this plus unmount cleanup |\\n\\nA request/response pair usually reuses one name: the client dispatches\\n`LEVEL_GET`, the bound service handler dispatches `LEVEL_GET` back with\\nthe answer.\\n\\n### Boot and player lifecycle\\n\\n`READY` (client -> `PlayerService`, fires its `PlayerReady` signal) is\\ndispatched by `Entry.client.luau` once data has loaded.\\n`PLAYER_JOINED`, `PLAYER_INACTIVE`, `PLAYER_LIVES` and\\n`PLAYER_LIVES_START` are server broadcasts out of `PlayerService` and\\n`BaseGameMode`. `UNLOCK_CHARACTER_MOVEMENT` and `PLAYERS_SPECTATE` are\\nbound in `Handlers/Core` and `Handlers/Player`.\\n\\n### Profile and progression\\n\\n`PROFILE_FETCH`, `PROFILE_GET`, `GET_PLAYER_STATS` and `GET_SCOREBOARD`\\nare bound in `Handlers/Profile`; `ProfileService` answers with\\n`PROFILE_GET`, `PROFILE_GET_LEADERBOARD_STATS`, `PROFILE_GET_SCOREBOARD`\\nand `PROFILE_RESET`. Note that bulk profile data does *not* travel this\\nway \u2014 it replicates through the Profile Replica, which the client picks up\\nin `DataController`.\\n\\n`LEVEL_GET`, `LEVEL_XP_NEEDED`, `LEVEL_PROGRESS` and `LEVEL_OVERVIEW` are\\nbound in `Handlers/Level` and answered by `LevelService` under the same\\nnames.\\n\\n### UI\\n\\nServer-driven UI. All are server -> client:\\n\\n* `UI_COUNTDOWN` ([CountdownPayload]) \u2014 `RootOverlay` renders the timer\\n* `UI_MESSAGE`, `UI_HINT` \u2014 `MessageOverlay`\\n* `UI_TOAST` \u2014 `ToasterPortal`\\n* `UI_DIALOG` \u2014 `DialogPortal`\\n* `UI_NOTIFICATION` \u2014 re-fired by `MessageController.ShowNotification`\\n* `UI_MUSIC`, `UI_MUSIC_STOP`, `CHAT_ALERT` \u2014 dispatched, not yet consumed\\n\\n### Inventory and hotbar\\n\\nClient -> server, all bound in `Handlers/Inventory`, all dispatched from\\n`InventoryPortal` drag-and-drop except the last two, which come from\\n`HotbarPortal`: `INVENTORY_MOVE_TO_HOTBAR` ([InventoryMoveToHotbarPayload]),\\n`HOTBAR_MOVE_TO_INVENTORY` ([HotbarMoveToInventoryPayload]),\\n`HOTBAR_SWAP_SLOTS` ([HotbarSwapSlotsPayload]),\\n`INVENTORY_SWAP_BAG_SLOTS` ([InventorySwapBagSlotsPayload]),\\n`HOTBAR_SELECT`, `HOTBAR_DESELECT`.\\n\\n### Shop and market\\n\\nRequests bound in `Handlers/Shop`, `Handlers/SeedShop`,\\n`Handlers/PlayerMarket` and `Handlers/Products`: `SHOP_PURCHASE`,\\n`SHOP_PURCHASE_STOCK`, `SHOP_PREPARE_ROBUX_PURCHASE`, `SHOP_SELL_ITEM`,\\n`SHOP_SELL_ALL`, `SHOP_EQUIP`, `SHOP_UNEQUIP`, `SHOP_GET_INVENTORY`,\\n`SHOP_REMOVE_ITEM`, `PLAYER_MARKET_CLAIM`, `PRODUCTS_GET`.\\n\\nServer notifications: `SHOP_INVENTORY`, `SHOP_REFRESH`,\\n`ITEM_SHOP_ITEM_ADD` (also drives an FTUE step), `ITEM_SHOP_ERROR`,\\n`ITEM_SHOP_CRATE_OPEN`, `ITEM_SELL_SUCCESS`, `ITEM_SELL_ERROR`.\\n\\nCosmetics: `KILL_EFFECT` ([KillEffectPayload], unreliable, everyone) from\\n`CosmeticService.playKillEffect` to `KillEffectController`.\\n\\n### Bases and props\\n\\nDispatched from the shared prop classes, which run on both sides:\\n`BASE_REMOVE_PROP`, `BASE_START_PROP_DESTRUCTION`\\n([StartPropDestructionPayload]), `BASE_UPGRADE_PROP`, `PROP_REMOTE_INPUT`\\n([PropRemoteInputPayload]), and the developer-product preparation actions\\n`SOIL_PREPARE_INSTANT_GROW_PURCHASE`, `SOIL_PREPARE_STEAL_CROP_PURCHASE`,\\n`SOIL_PREPARE_STEAL_PRODUCE_PURCHASE`. [PlacePropPayload],\\n[MovePropPayload], [SoilAddSeedPayload], [AnimalPenAddEggPayload],\\n[BasePrepareGrowAllCropsPurchasePayload] and\\n[BasePrepareHarvestAllCropsPurchasePayload] describe the base-editing\\nsurface.\\n\\n### Rounds, minigames and voting\\n\\nRound state is broadcast by `BaseGameMode` and `GameService`:\\n`ROUND_START`, `ROUND_END`, `ROUND_ALIVE_COUNT`, `GAME_ROUND_INFO`\\n([GameInfoRoundPayload]) and `GAME_ROUND_SUMMARY`\\n([GameInfoSummaryPayload]) \u2014 the last two feed the `useRoundInfo` hook,\\nthe first three feed `RoundInfoOverlay` and `ScoreboardPortal`.\\n`ROUND_ROLE` ([RoleRevealPayload]) is sent by a game mode to each player\\nas they get a role, and drives the role reveal in `RoundInfoOverlay`.\\n`TEAM_JOIN` / `TEAM_LEAVE` are subscribed by `BaseGameMode`.\\n\\nGame selection: `MINIGAMES_INIT_CHOOSE_NEXT`, `MINIGAMES_PLAYER_CAN_CHOOSE`,\\n`MINIGAMES_NEXT_QUEUED_GAME` (bound in `Handlers/Minigames`),\\n`MINIGAMES_CHOOSE_NEXT` and `MINIGAME_CHOOSE_GAME`.\\n\\nVoting: `VOTE_START`, `VOTE_ENTRIES_UPDATE`, `VOTE_RESULT_DISPLAY` and\\n`VOTE_DISABLE` are dispatched by `VoteService` / `GameService` and consumed\\nby `VoteOverlay`; `VOTE_CAST` and `VOTE_RESULTS_GET` are bound in\\n`Handlers/Vote`.\\n\\nScoreboard: `START_SCOREBOARD` and `UPDATE_SCOREBOARD`\\n([ScoreboardPayload], [ScoreboardTeam]) are consumed by `ScoreboardPortal`.\\n\\n### Queue\\n\\n`QUEUE_GET`, `QUEUE_LEAVE`, `QUEUE_SELECT_MAX` and `QUEUE_SKIP_VOTE` are\\ndispatched by `QueueController` and bound in `Features/Queue/Handler`;\\n`QUEUE_UPDATE`, `QUEUE_ALL_STATES`, `QUEUE_PROMPT_SELECT` and\\n`QUEUE_REMOVED` come back the other way.\\n\\n### Vehicles, mineables, teleports\\n\\n`VEHICLE_SPAWN`, `VEHICLE_DESPAWN`, `VEHICLE_LOG_DISTANCE` and\\n`VEHICLE_GET_ATTACHMENTS` are bound in `Handlers/Vehicle`;\\n`VEHICLE_START_CONTROL` comes back from `VehicleService`.\\n`MINEABLE_HIT` (client -> `Features/Mineables/Handler`) and\\n`MINEABLE_AWARD` (server -> `MineablesController`, which spawns the drop)\\nare the mining loop. `TELEPORT_REQUEST` and `BASE_TELEPORT_REQUEST` are\\ndispatched by the `TeleportPad` watcher and `QuickBar`.\\n\\n### Gear\\n\\n`GEAR_ACTIVATE` ([GearActivatePayload]) and `GEAR_SET_SKIN`\\n([GearSetSkinPayload]) are dispatched by Gearkit\'s `Handheld` and bound in\\n`GearService`. The server answers with `GEAR_ECHO`\\n([GearEchoPayload], unreliable, everyone but the owner),\\n`GEAR_CUE` ([GearCuePayload], unreliable, everyone) and\\n`GEAR_STATE` ([GearStatePayload], owner only). See\\nthe `firebit-dev/gearkit` package.\\n\\n### Security, monetization, analytics\\n\\n`SECURITY_INIT` / `SECURITY_PING` / `SECURITY_PONG` are the anti-exploit\\nhandshake described in `SecurityController`; `SECURITY_GET_RESPONSES` and\\n`SECURITY_OFFENSE` round out the family. `MONETIZATION_FAVORITED_GAME` is\\nbound in `Handlers/Monetization`. `ANALYTICS_ERROR` and `ANALYTICS_EVENT`\\nare analytics reports.\\n\\n:::note\\n`ADD_MONEY` is bound in `Handlers/Cheat` to a honeypot. It is not part of\\nthe protocol \u2014 nothing legitimate dispatches it, and anything that does is\\nan exploit attempt.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/survival-islands - proprietary and confidential.","source":{"line":166,"path":"src/Shared/Types/Actions.luau"}}')}}]);